import {initializeNode} from './gathering.mjs?v=0.6';
import {ascensionRecipe} from './equipment-system.mjs?v=0.6';
import {GRADES,MATERIALS,SLOTS,PETS,amount,addMaterial,syncLegacy,canMaterials,spendMaterials,gearRecipe,enhancementRecipe,newItem} from './economy.mjs?v=0.6';
import {REGIONS,regionById,regionUnlocked,regionQuest,regionValue,mapNodes,mapEnemies,mapObstacles} from './regions.mjs?v=0.6';
export const craftingActions={
 fuseMaterial(kind,grade,batches=1){if(!MATERIALS[kind]||!Number.isInteger(grade)||grade<0||grade>=4||!Number.isInteger(batches)||batches<1||batches>1000)return false;if(!spendMaterials(this.s,{[kind]:10*batches},grade)){this.say('Chưa đủ nguyên liệu: mỗi lần ghép cần 10 cùng màu.');return false;}let trade=0;for(let i=0;i<batches;i++){let t=this.random()<.2;addMaterial(this.s,kind,grade+1,1,t);trade+=+t;}this.say(`Ghép thành công ${batches} ${MATERIALS[kind].name} ${GRADES[grade+1].color} · ${trade} giao dịch, ${batches-trade} khóa.`);return true;},
 refineStone(grade,batches=1){if(!Number.isInteger(grade)||!GRADES[grade]||!Number.isInteger(batches)||batches<1||batches>100)return false;if(!spendMaterials(this.s,{ore:2*batches,energy:batches},grade))return false;for(let i=0;i<batches;i++)addMaterial(this.s,'stone',grade,1,this.random()<.2);this.say(`Đã luyện ${batches} đá cường hóa ${GRADES[grade].color}.`);return true;},
 canCraftGear(slot,grade){const r=gearRecipe(slot,grade);return !!r&&this.s.items.length<500&&this.s.gold>=r.gold&&canMaterials(this.s,r.materials,grade);},
 craftGear(slot,grade){if(!this.canCraftGear(slot,grade)){this.say('Chưa đủ vật liệu / đồng, hoặc kho đã đủ 500 món.');return false;}const r=gearRecipe(slot,grade);spendMaterials(this.s,r.materials,grade);this.s.gold-=r.gold;const item=newItem(this.s,slot,grade,1,0,this.random()<.2);if(this.s.map!=='van'&&regionById(this.s.map).grade===grade)this.s.regions[this.s.map].craft++;this.say(`Đã chế ${SLOTS[slot].name} ${GRADES[grade].color} bậc I · ${item.tradable?'Có thể giao dịch':'Khóa'}.`);return item;},
 equip(id){const it=this.s.items.find(i=>i.id===id);if(!it)return false;this.s.equipped[it.slot]=id;this.say('Đã trang bị '+SLOTS[it.slot].name+'.');return true;},
 unequip(slot){if(!Object.hasOwn(this.s.equipped,slot))return false;delete this.s.equipped[slot];return true;},
 protectItem(id){const it=this.s.items.find(i=>i.id===id);if(!it)return false;it.protected=!it.protected;return true;},
 eligibleIngredient(it){return it&&!it.protected&&!Object.values(this.s.equipped).includes(it.id);},
 canMergeItems(aId,bId){const a=this.s.items.find(i=>i.id===aId),b=this.s.items.find(i=>i.id===bId);return aId!==bId&&this.eligibleIngredient(a)&&this.eligibleIngredient(b)&&a.slot===b.slot&&a.grade===b.grade&&a.tier===b.tier&&a.tier<4&&a.enhance===0&&b.enhance===0;},
 mergeItems(aId,bId){if(!this.canMergeItems(aId,bId)){this.say('Chọn 2 món cùng loại, màu, bậc I–III, +0; tháo mặc và bỏ bảo vệ trước.');return false;}const a=this.s.items.find(i=>i.id===aId);this.s.items=this.s.items.filter(i=>i.id!==aId&&i.id!==bId);const it=newItem(this.s,a.slot,a.grade,a.tier+1,0,this.random()<.2);this.say(`Ghép thành công ${SLOTS[it.slot].name} bậc ${it.tier} · ${it.tradable?'Giao dịch':'Khóa'}.`);return it;},
 enhanceItem(id){const it=this.s.items.find(i=>i.id===id);if(!it||it.protected||it.enhance>=8)return false;const r=enhancementRecipe(it);if(this.s.gold<r.gold||!spendMaterials(this.s,r.materials,it.grade)){this.say('Cần đá cường hóa cùng màu và đủ đồng.');return false;}this.s.gold-=r.gold;it.enhance++;this.say(`${SLOTS[it.slot].name} đã lên +${it.enhance}.`);return true;},
 canAscendItem(id){const it=this.s.items.find(i=>i.id===id);if(!this.eligibleIngredient(it)||it.tier!==4||it.enhance!==8||it.grade>=4)return false;const r=ascensionRecipe(it);return this.s.gold>=r.gold&&canMaterials(this.s,r.materials,it.grade+1);},
 ascendItem(id){if(!this.canAscendItem(id)){this.say('Cần đồ bậc IV +8 chưa mặc/bảo vệ và công thức màu kế tiếp.');return false;}const it=this.s.items.find(i=>i.id===id),r=ascensionRecipe(it);spendMaterials(this.s,r.materials,it.grade+1);this.s.gold-=r.gold;this.s.items=this.s.items.filter(i=>i.id!==id);const out=newItem(this.s,it.slot,it.grade+1,1,0,this.random()<.2);if(this.s.map!=='van'&&regionById(this.s.map).grade===out.grade)this.s.regions[this.s.map].craft++;this.say('Đã thăng phẩm: '+SLOTS[out.slot].name+' '+GRADES[out.grade].color+' bậc I +0.');return out;},
 upgradePet(key){const p=PETS[key],lv=this.s.petLevels[key];if(!p||lv>=5||!regionUnlocked(this.s,p.unlock)){this.say('Pet chưa mở hoặc đã tối đa.');return false;}const c=100+(lv||0)*90;if(this.s.gold<c||!spendMaterials(this.s,{essence:(lv||0)+2},p.grade)){this.say('Chưa đủ đồng và linh phách cùng màu pet.');return false;}this.s.gold-=c;this.s.petLevels[key]++;if(Object.hasOwn(this.s.spirits,key))this.s.spirits[key]=this.s.petLevels[key];this.s.spirit=key;this.say(`${p.name} bậc ${this.s.petLevels[key]}.`);return true;},
 choosePet(key){if(!PETS[key]||!this.s.petLevels[key])return false;this.s.spirit=key;return true;}
};
export function regionActions({NPCS,SHRINES,OBSTACLES,NODE_DEFS,ENEMY_DEFS,ENEMY_TYPES,distance}){return {
 getRegion(){return regionById(this.s.map);},
 currentQuest(){return this.s.map==='van'?null:regionQuest(this.s);},
 loadRegion(){const r=this.getRegion(),base=r.id==='van',scale=1+r.grade*.75;this.npcs=base?NPCS:[{id:'lam',name:r.npc,x:32,z:89,color:0xb49965},{id:'forge',name:'Lò rèn lưu động',x:22,z:103,color:0x7b6470}];this.shrines=base?SHRINES:[];this.obstacles=base?OBSTACLES:mapObstacles(r);this.nodes=mapNodes(r).map(n=>initializeNode(this.s,n,this.random));this.enemies=(base?ENEMY_DEFS.map((d,i)=>i<11?{...d,x:mapEnemies(r)[i].x,z:mapEnemies(r)[i].z}:d):mapEnemies(r)).map(d=>{const type=ENEMY_TYPES[d.type],boss=!!type.boss,dead=base?((d.type==='guardian'&&this.s.counts.guardian)||(d.type==='lord'&&this.s.counts.lord)):boss&&this.s.regions[r.id].boss;return {...d,...type,name:d.name||type.name,home:{x:d.x,z:d.z},hp:Math.round(type.hp*scale),max:Math.round(type.hp*scale),atk:Math.round(type.atk*(1+r.grade*.32)),xp:Math.round(type.xp*scale),gold:Math.round(type.gold*scale),dead:dead?999999:0,wind:0,cd:0,stun:0};});this.regionRevision=(this.regionRevision||0)+1;},
 travel(id){const i=REGIONS.findIndex(r=>r.id===id);if(i<0||!regionUnlocked(this.s,i)){this.say('Hoàn thành cốt truyện khu vực trước để mở map này.');return false;}const portal=this.getRegion().portal;if(distance(this.s,portal)>6){this.say('Đến cổng dịch chuyển trước. Chọn “Đến cổng” trên bản đồ.');return false;}this.stop();this.selected=null;this.mount=false;this.s.map=id;Object.assign(this.s,this.getRegion().spawn);this.loadRegion();this.ward=4;this.emit('mapchange');this.say('Đã đến '+this.getRegion().name+'.');return true;},
 regionalReady(){const q=regionQuest(this.s);return !!q&&q.goals.every(g=>regionValue(this.s,g.key)>=g.need);},
 regionalInteract(id){const npc=this.npcs.find(n=>(!id||id===n.id)&&distance(this.s,n)<5.5);if(npc){if(npc.id==='forge'){this.emit('panel',{panel:'forge'});return;}const q=regionQuest(this.s);this.stop();this.emit('regiondialog',{npc:npc.name,text:q?this.regionalReady()?q.story:q.text:'Khu vực đã bình yên. Cổng dịch chuyển đã mở đường tới chặng tiếp theo.',claim:this.regionalReady(),title:q?.title||'Lời nhắn của người giữ ấn'});return;}return false;},
 claimRegion(){const q=regionQuest(this.s),npc=this.npcs.find(n=>n.id==='lam');if(!q||!this.regionalReady()||distance(this.s,npc)>6)return false;const p=this.s.regions[this.s.map];p.quest++;this.s.gold+=q.gold;this.addXP(q.xp);addMaterial(this.s,'essence',this.getRegion().grade,3);if(p.quest===4){addMaterial(this.s,'feather',this.getRegion().grade,8);this.say('Đã hoàn thành '+this.getRegion().name+'! Mở bản đồ thế giới để tiếp tục.');}this.emit('quest');return true;},
 regionalAuto(){const q=regionQuest(this.s);if(!q){this.stop();this.say('Đã hoàn thành khu vực. Mở bản đồ để chuyển map.');return;}if(this.regionalReady()){const n=this.npcs.find(n=>n.id==='lam');if(distance(this.s,n)<4.8)this.regionalInteract('lam');else this.navigate(n.x,n.z+2);return;}const goal=q.goals.find(g=>regionValue(this.s,g.key)<g.need);if(goal.key==='regionalCraft'){this.stop();this.emit('panel',{panel:'forge'});return;}const previous=this.mode,oldType=this.farmType,oldGrade=this.s.gatherGrade;this.s.gatherGrade=-1;this.mode=goal.key==='regionalKills'||goal.key==='regionalBoss'?'farm':{regionalOre:'ore',regionalHerb:'herb',regionalEnergy:'energy'}[goal.key];this.farmType=goal.key==='regionalBoss'?'guardian':'wolf';this.autoStep();this.mode=previous;this.farmType=oldType;this.s.gatherGrade=oldGrade;}
};}
